import {unzlibSync} from 'fflate';
export const ISLAND_RASTER_SIZE=321;
export const ISLAND_RASTER_PEAKS=[79.25274949766532,76.8857844107505,93.53109094634947,67.92503336055358,81.3530263104476,101.1157829449285,84.98440785950038,85.64312457222024,90.6822926265576,97.9933088528934,112.53665740904769,98.71432283060483,87.84522426218672,89.80946417330536,106.59147376351277,88.37959393093243,99.88086231588733,86.50457462662122,111.72140930059085,96.3719436950225];
const packed=["","","","","","","","","","","","","","","","","","","",""],cache=new Map();
export function islandRaster(variant){
 let grid=cache.get(variant);if(grid)return grid;
 const raw=atob(packed[variant]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));
 const data=unzlibSync(bytes),view=new DataView(data.buffer,data.byteOffset,data.byteLength);
 grid=new Float32Array(103041);for(let i=0;i<grid.length;i++){const v=view.getInt8(i)/127;grid[i]=Math.sign(v)*v*v*300;}
 cache.set(variant,grid);return grid;
}
